def prior_macro(series: list[dict[str, Any]], signal_date: str) -> dict[str, Any] | None:
    lo, hi = 0, len(series)
    while lo < hi:
        mid = (lo + hi) // 2
        if series[mid]["date"] < signal_date:
            lo = mid + 1
        else:
            hi = mid
    return series[lo - 1] if lo else None
